<function_calls>
<invoke name="Write">
<parameter name="file_path">/Users/user/ErrorBoundary.tsx</parameter>
<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });
    console.error("[ErrorBoundary] Caught render error:", error);
    console.error("[ErrorBoundary] Component stack:", errorInfo.componentStack);
    this.props.onError?.(error, errorInfo);
  }

  private handleRetry = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { error, errorInfo } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      return (
        <div role="alert" style={styles.container}>
          <h2 style={styles.heading}>Something went wrong</h2>
          <p style={styles.message}>{error.message}</p>
          {process.env.NODE_ENV !== "production" && errorInfo && (
            <details style={styles.details}>
              <summary style={styles.summary}>Component stack</summary>
              <pre style={styles.stack}>{errorInfo.componentStack}</pre>
            </details>
          )}
          <button onClick={this.handleRetry} style={styles.button}>
            Try again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    margin: "2rem auto",
    maxWidth: 600,
    borderRadius: 8,
    border: "1px solid #fca5a5",
    backgroundColor: "#fff1f2",
    fontFamily: "system-ui, sans-serif",
  },
  heading: {
    margin: "0 0 0.5rem",
    color: "#b91c1c",
    fontSize: "1.25rem",
  },
  message: {
