<invoke name="Write">
<parameter name="file_path">/Users/user/ErrorBoundary.example.tsx</parameter>
<parameter name="content">import React, { ErrorInfo, useState } from "react";
import { ErrorBoundary } from "./ErrorBoundary";

function BrokenComponent() {
  throw new Error("Intentional render failure");
}

function Counter() {
  const [count, setCount] = useState(0);
  if (count === 3) throw new Error("Count reached 3!");
  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>Increment</button>
    </div>
  );
}

export default function App() {
  function handleError(error: Error, info: ErrorInfo) {
    // Send to an error reporting service here
    console.log("Reported:", error.message, info);
  }

  return (
    <div style={{ padding: "2rem" }}>
      {/* Basic usage */}
      <ErrorBoundary onError={handleError}>
        <BrokenComponent />
      </ErrorBoundary>

      {/* With custom fallback */}
      <ErrorBoundary
        fallback={<p style={{ color: "red" }}>Custom fallback UI</p>}
        onError={handleError}
      >
        <Counter />
      </ErrorBoundary>
    </div>
  );
}
</parameter>
</invoke>
